from __future__ import annotations

from typing import Any

from plugin_contracts import PluginDefinition, result


def uppercase_plugin(payload: dict[str, Any]) -> dict[str, Any]:
    text = str(payload.get("text", "")).strip()
    if not text:
        return result(False, "text_required")
    return result(True, "ok", {"value": text.upper()})


def reverse_plugin(payload: dict[str, Any]) -> dict[str, Any]:
    text = str(payload.get("text", "")).strip()
    if not text:
        return result(False, "text_required")
    return result(True, "ok", {"value": text[::-1]})


def score_plugin(payload: dict[str, Any]) -> dict[str, Any]:
    text = str(payload.get("text", "")).strip()
    if not text:
        return result(False, "text_required")
    score = sum(ord(ch) for ch in text) % 100
    return result(True, "ok", {"score": score})


def failing_plugin(payload: dict[str, Any]) -> dict[str, Any]:
    return result(False, "forced_failure", {"input": dict(payload)})


def builtins() -> list[PluginDefinition]:
    return [
        PluginDefinition(action="uppercase", version="1.0", handler=uppercase_plugin, metadata={"builtin": True}),
        PluginDefinition(action="reverse", version="1.0", handler=reverse_plugin, metadata={"builtin": True}),
        PluginDefinition(action="score", version="1.0", handler=score_plugin, metadata={"builtin": True}),
        PluginDefinition(action="fail", version="1.0", handler=failing_plugin, metadata={"builtin": True}),
    ]


def names() -> list[str]:
    return sorted([item.action for item in builtins()])


def versions(action: str) -> list[str]:
    target = action.strip().lower()
    return sorted([item.version for item in builtins() if item.action == target])


def has_action(action: str) -> bool:
    return action.strip().lower() in names()


def describe() -> list[str]:
    return [f"{item.action}@{item.version}" for item in builtins()]


def count() -> int:
    return len(builtins())


def summary() -> dict[str, int]:
    out: dict[str, int] = {}
    for item in builtins():
        out[item.action] = out.get(item.action, 0) + 1
    return out

