        out: list[dict[str, Any]] = []
        for _ in range(max(0, int(times))):
            out.append(self.execute(dict(payload)))
        return out

    def replay_summary(self, payload: dict[str, Any], times: int = 1) -> dict[str, int]:
        results = self.replay(payload, times=times)
        success = 0
        failed = 0
        for item in results:
            if bool(item.get("ok", False)):
                success += 1
            else:
                failed += 1
        return {"success": success, "failed": failed}

    def execute_many(self, payloads: list[dict[str, Any]]) -> dict[str, Any]:
        return self.service.execute_many(payloads)

