        self,
        *,
        role: str,
        source_action: str,
        source_version: str,
        alias_action: str,
        alias_version: str,
    ) -> dict[str, Any]:
        plugin = self.registry.resolve(source_action, version=source_version)
        if plugin is None:
            return {"ok": False, "reason": "source_plugin_not_found"}
        return self.register(
            role=role,
            action=alias_action,
            version=alias_version,
            handler=plugin.handler,
            metadata={"alias_of": f"{source_action}@{source_version}"},
        )

    def clear_events(self) -> None:
        self.events.clear()

    def clear_all(self) -> None:
        self.registry.clear()
        self.clear_events()
        self.clear_runtime_metrics()

