from __future__ import annotations

from threading import Lock
from typing import Any

from plugin_contracts import PluginDefinition, plugin_key


class PluginRegistry:
    def __init__(self) -> None:
        self._lock = Lock()
        self._plugins: dict[str, PluginDefinition] = {}
        self._by_action: dict[str, list[str]] = {}

    def register(self, plugin: PluginDefinition) -> None:
        plugin.validate()
        key = plugin_key(plugin.action, plugin.version)
        with self._lock:
            self._plugins[key] = plugin
            action_key = plugin.action.strip().lower()
            versions = self._by_action.setdefault(action_key, [])
            if plugin.version not in versions:
                versions.append(plugin.version)
                versions.sort()

    def resolve(self, action: str, version: str | None = None) -> PluginDefinition | None:
        action_key = action.strip().lower()
        if not action_key:
            return None
        with self._lock:
            if version is not None:
                return self._plugins.get(plugin_key(action_key, version))
            versions = self._by_action.get(action_key, [])
            if not versions:
                return None
            latest = versions[-1]
            return self._plugins.get(plugin_key(action_key, latest))

    def list_actions(self) -> list[str]:
        with self._lock:
            return sorted(self._by_action.keys())

