from plugin_registry import PluginRegistry
from request_parser import parse
from runtime_state import RuntimeState
from tenant_policy import can_execute_custom_plugin, can_register_plugin, can_use_action, category


class PluginService:
    def __init__(self, *, registry: PluginRegistry, events: EventLog, metrics: Metrics, runtime: RuntimeState) -> None:
        self._registry = registry
        self._events = events
        self._metrics = metrics
        self._runtime = runtime

    def load_builtins(self) -> None:
        for plugin in builtins():
            self._registry.register(plugin)
        self._metrics.incr("builtin_loaded", len(builtins()))

    def register_plugin(
        self,
        *,
        role: str,
        action: str,
        version: str,
        handler,
        metadata: dict[str, Any] | None = None,
    ) -> dict[str, Any]:
        allowed, reason = can_register_plugin(role)
        if not allowed:
            self._metrics.incr("register_forbidden")
            return {"ok": False, "reason": reason}
        plugin = PluginDefinition(action=action, version=version, handler=handler, metadata=dict(metadata or {}))
        self._registry.register(plugin)
        self._events.add("plugin_registered", {"action": action, "version": version})
        self._metrics.incr("plugin_registered")
        return {"ok": True, "reason": "registered"}

    def execute(self, payload: dict[str, Any]) -> dict[str, Any]:
        try:
            ctx, version = parse(payload)
        except Exception as exc:
            self._metrics.incr("parse_error")
            return {"ok": False, "reason": f"invalid_payload:{exc}"}

        role = str(payload.get("role", ctx.payload.get("role", "member"))).strip().lower()
        allowed, reason = can_use_action(role, ctx.action)
        if not allowed:
            self._events.add("plugin_denied", {"action": ctx.action, "reason": reason, "tenant_id": ctx.tenant_id})
            self._metrics.incr("plugin_denied")
            return {"ok": False, "reason": reason}

        if category(ctx.action) == "custom":
            allowed_custom, custom_reason = can_execute_custom_plugin(role)
            if not allowed_custom:
                self._events.add(
                    "plugin_denied",
                    {"action": ctx.action, "reason": custom_reason, "tenant_id": ctx.tenant_id},
                )
                self._metrics.incr("plugin_denied")
                return {"ok": False, "reason": custom_reason}

        plugin = self._registry.resolve(ctx.action, version=version)
        if plugin is None:
            self._events.add("plugin_missing", {"action": ctx.action, "tenant_id": ctx.tenant_id})
            self._metrics.incr("plugin_missing")
            return {"ok": False, "reason": "plugin_not_found"}

        try:
            plugin_result = plugin.handler(ctx.payload)
        except Exception as exc:
            self._events.add("plugin_error", {"action": ctx.action, "error": str(exc), "tenant_id": ctx.tenant_id})
            self._metrics.incr("plugin_error")
            return {"ok": False, "reason": "plugin_exception"}

        # Bug: plugin_result ok flag is ignored; failed plugin still treated as success.
        self._events.add("plugin_executed", {"action": ctx.action, "tenant_id": ctx.tenant_id})
        self._metrics.incr("plugin_executed")
        self._runtime.set(f"last:{ctx.tenant_id}", {"action": ctx.action, "result": dict(plugin_result)})
        return {"ok": True, "reason": "ok", "result": plugin_result}

    def diagnostics(self) -> dict[str, Any]:
        return {
            "registry": self._registry.snapshot(),
            "events": self._events.summary(),
            "metrics": self._metrics.snapshot(),
            "runtime_count": self._runtime.count(),
            "runtime": self._runtime.snapshot(),
        }

    def clear_runtime(self) -> None:
        self._runtime.clear()

    def resolve_action(self, action: str, version: str | None = None) -> str:
        plugin = self._registry.resolve(action, version=version)
        if plugin is None:
            return ""
        return f"{plugin.action}@{plugin.version}"

    def execute_many(self, payloads: list[dict[str, Any]]) -> dict[str, Any]:
        results: list[dict[str, Any]] = []
        success = 0
        failed = 0
        for payload in payloads:
            result = self.execute(payload)
            results.append(result)
            if bool(result.get("ok", False)):
                success += 1
            else:
                failed += 1
        return {"success": success, "failed": failed, "results": results}

    def replay(self, payload: dict[str, Any], times: int = 1) -> list[dict[str, Any]]:
        out: list[dict[str, Any]] = []
        for _ in range(max(0, int(times))):
            out.append(self.execute(dict(payload)))
        return out

    def replay_summary(self, payload: dict[str, Any], times: int = 1) -> dict[str, int]:
        results = self.replay(payload, times=times)
        success = 0
        failed = 0
        for item in results:
            if bool(item.get("ok", False)):
                success += 1
            else:
                failed += 1
        return {"success": success, "failed": failed}

    def register_builtin_overrides(self, plugins: list[PluginDefinition]) -> int:
        count = 0
        for plugin in plugins:
            self._registry.register(plugin)
            count += 1
            self._metrics.incr("plugin_registered")
        return count

